import{_ as e,r as n,o,c as l,e as a,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"视图和部件 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"部件","slug":"部件","link":"#部件","children":[{"level":3,"title":"提示部件","slug":"提示部件","link":"#提示部件","children":[]},{"level":3,"title":"检查提示是否隐藏","slug":"检查提示是否隐藏","link":"#检查提示是否隐藏","children":[]}]},{"level":2,"title":"布局和子布局","slug":"布局和子布局","link":"#布局和子布局","children":[{"level":3,"title":"带侧边栏的表单","slug":"带侧边栏的表单","link":"#带侧边栏的表单","children":[]}]}],"relativePath":"2.x/zh-cn/backend/views-partials.md","filePath":"2.x/zh-cn/backend/views-partials.md"}'),r={name:"2.x/zh-cn/backend/views-partials.md"};function k(d,s,u,g,m,h){const t=n("pre-heading"),p=n("post-heading");return o(),l("div",null,[a(t),s[0]||(s[0]=c("h1",null,"视图和部件",-1)),a(p),s[1]||(s[1]=i(`<h2 id="部件"><a href="#部件" class="header-anchor">#</a> 部件</h2><p>后端部件文件是扩展名为 <strong>htm</strong> 的文件，位于 <a href="./controllers-ajax.html">控制器视图</a> 目录中。 部件文件名应以下划线开头：<em>_partial.htm</em>。 部件可以从后端页面或另一个部件呈现。 使用控制器的 <code>makePartial</code> 方法来渲染部件。 该方法采用两个参数 - 部件名称和要传递给部件的可选变量数组。 例子：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;sidebar&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;showHeader&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="提示部件"><a href="#提示部件" class="header-anchor">#</a> 提示部件</h3><p>您可以在后端呈现信息面板，称为提示，用户可以隐藏这些面板。 第一个参数应该是唯一的键，用于记住提示是否已隐藏。 第二个参数是对部件视图的引用。 除了一些提示属性外，第三个参数可以是一些传递给部件的额外视图变量。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeHintPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_hint_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;my_hint_partial&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;foo&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>您还可以通过将键值设置为null值来禁用隐藏提示的功能。 此提示将始终显示：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeHintPartial</span><span class="token punctuation">(</span><span class="token constant">null</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;my_hint_partial&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>以下属性可用：</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>type</strong></td><td>设置提示的颜色，支持的类型：danger(危险), info(信息), success(成功), warning(警告)。 默认值：info。</td></tr><tr><td><strong>title</strong></td><td>向提示添加标题部分。</td></tr><tr><td><strong>subtitle</strong></td><td>除了标题之外，在标题部分第二行添加子标题。</td></tr><tr><td><strong>icon</strong></td><td>除了标题之外，在标题部分添加一个图标。</td></tr></tbody></table></div><h3 id="检查提示是否隐藏"><a href="#检查提示是否隐藏" class="header-anchor">#</a> 检查提示是否隐藏</h3><p>如果您正在使用提示，您可能会发现检查用户是否隐藏了它们很有用。 使用 <code>isBackendHintHidden</code> 方法很容易做到这一点。 它接受一个参数，这是您在最初调用 <code>makeHintPartial</code> 时指定的唯一键。 如果提示被隐藏，该方法将返回 true，否则返回 false：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">isBackendHintHidden</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_hint_key&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token comment">&lt;!-- 当提示被隐藏时做一些事情 --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p><a id="oc-layouts-and-child-layouts"></a></p><h2 id="布局和子布局"><a href="#布局和子布局" class="header-anchor">#</a> 布局和子布局</h2><p>后端布局驻留在插件的可选 <strong>layouts/</strong> 目录中。 使用控制器对象的 <code>$layout</code> 属性设置自定义布局。 系统布局默认称为<code>default</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var string 用于视图的布局。
 */</span>
<span class="token keyword">public</span> <span class="token variable">$layout</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mycustomlayout&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>布局还提供了将自定义 CSS 类附加到 BODY 标签的选项。 这可以通过控制器的 <code>$bodyClass</code> 属性进行设置。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var string 要添加到布局的正文 CSS 类。
 */</span>
<span class="token keyword">public</span> <span class="token variable">$bodyClass</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;compact-container&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>这些 body 类可用于默认布局：</p><ul><li><strong>compact-container</strong> - 在任何地方不使用任何填充。</li><li><strong>slim-container</strong> - 不使用左右填充。</li><li><strong>breadcrumb-flush</strong> - 告诉页面面包屑与下面的元素齐平放置。</li></ul><h3 id="带侧边栏的表单"><a href="#带侧边栏的表单" class="header-anchor">#</a> 带侧边栏的表单</h3><p>布局也可以以与局部相同的方式使用，更像是全局局部。 该系统提供了一个名为<code>form-with-sidebar</code>的示例，并演示了一种实现子布局结构的新颖方法。</p><p>在使用此布局样式之前，请确保您的控制器使用主体类 <code>compact-container</code>，方法是在控制器的操作方法或构造函数中设置它。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">bodyClass</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;compact-container&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>此布局使用两个占位符，一个名为 <strong>form-contents</strong> 的主要内容区域和一个名为 <strong>form-sidebar</strong> 的补充侧边栏。 这是一个例子：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">&lt;!-- 主要内容 --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-contents&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    Main content
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token comment">&lt;!-- 补充侧边栏 --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-sidebar&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    Side content
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token comment">&lt;!-- 执行布局 --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;body&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span><span class="token operator">=&gt;</span><span class="token string single-quoted-string">&#39;layout stretch&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeLayout</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-with-sidebar&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>通过覆盖每个后端布局使用的 <strong>body</strong> 占位符，执行布局在最后一部分。 它用 <code>&lt;form /&gt;</code> HTML 标签包裹所有内容，并呈现名为 <strong>form-with-sidebar</strong> 的子布局。 该文件位于 <code>modules\\backend\\layouts\\form-with-sidebar.htm</code> 中。</p>`,28))])}const b=e(r,[["render",k]]);export{v as __pageData,b as default};
